commands.usageExample:
{
  "tên lệnh": "api_create_leader",
  "tham số": {
    "điểm": [[0, 0, 0], [50, 50, 0], [100, 50, 0]],
    "annotation": "Đây là chú thích của người lãnh đạo",
    "hasArrowhead": đúng,
    "tên lớp": "0"
  }
}

{
  "tên lệnh": "api_create_mtext",
  "tham số": {
    "vị trí": [100, 100, 0],
    "text": "Dòng đầu tiên\nDòng thứ hai",
    "chiều rộng": 200,
    "chiều cao": 10,
    "tên lớp": "0"
  }
}

{
  "tên lệnh": "api_batch_get_entity_info",
  "tham số": {
    "entityHandles": ["27E2BF", "27E2C0", "27E2C1"]
  }
}

Hoặc lấy tất cả các thực thể mà không cung cấp tham số:
{
  "tên lệnh": "api_batch_get_entity_info",
  "tham số": {}
}

{
  "tên lệnh": "api_create_block_def định",
  "tham số": {
    "blockName": "Khối mới",
    "basePoint": [0, 0, 0],
    "entityHandles": ["27E2C0", "27E2D0"],
    "xóa bản gốc": sai,
    "định nghĩa thuộc tính": [
      {
        "thẻ": "TAG1",
        "prompt": "Hãy nhập giá trị của TAG1",
        "giá trị mặc định": "",
        "vị trí": [10, 0, 0]
      }
    ]
  }
}

{
  "tên lệnh": "api_batch_create_texts",
  "tham số": {
    "jsonFilePath": "C:/path/texts.json",
    "createLayerIfNotExists": đúng
  }
}
// hoặc inline: "texts": [ { "position": [100,100,0], "text": "Device tag", "height": 12 } ]
// nội dung file jsonFilePath là mảng văn bản (mảng trần) hoặc đối tượng {"texts": [...]}, mã hóa UTF-8.

{
  "tên lệnh": "api_calc_distance",
  "tham số": {
    "điểm1": [0, 0, 0],
    "điểm2": [100, 100, 0]
  }
}
// Hoặc sử dụng mã điều khiển thực thể để tính khoảng cách ngắn nhất giữa hai thực thể
{
  "tên lệnh": "api_calc_distance",
  "tham số": {
    "entityHandle1": "27E2BF",
    "entityHandle2": "27E2C0"
  }
}

{
  "tên lệnh": "api_window_select_with_filter",
  "tham số": {
    "entityTypes": ["LINE", "CIRCLE"],
    "layerNames": ["0", "Thiết bị"],
    "promptMessage": "Hãy chọn khu vực"
  }
}
